/* generated child CSS: 09-vertical-section/section.h2-narrative-only/block.css */
/* lab-ui block · section.h2-narrative-only
   Depends: 00-tokens/tokens.css. Light theme. */

.snarr {
  padding-block: clamp(4rem, 7vw, 6.5rem);
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
.snarr .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.snarr-grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4rem);
  align-items: start;
  max-width: 58rem;
  padding-left: clamp(1rem, 2vw, 1.5rem);
}
.snarr-grid::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.35rem;
  bottom: 0.35rem;
  width: 3px;
  border-radius: 999px;
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
}
.snarr[data-has-glyph="true"] .snarr-grid {
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  max-width: none;
  align-items: center;
}
.snarr[data-has-glyph="false"] .snarr-glyph {
  display: none;
}

.snarr-text .eyebrow {
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  text-transform: uppercase;
  letter-spacing: var(--type-eyebrow-tracking);
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  margin: 0 0 14px;
}
.snarr-title {
  margin: 0 0 20px;
  font-weight: var(--type-h2-weight);
  font-size: var(--type-h2-size);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
  color: var(--color-heading);
}
.snarr-body { display: grid; gap: 14px; max-width: 42rem; }
.snarr-body p {
  margin: 0;
  font-size: var(--type-lead-size);
  line-height: var(--type-lead-leading);
  color: var(--color-text);
}

.snarr-glyph {
  display: grid;
  place-items: center;
}
.snarr-glyph svg {
  width: 100%;
  max-width: 360px;
  height: auto;
  display: block;
}

@media (max-width: 900px) {
  .snarr-grid { grid-template-columns: 1fr; gap: 28px; }
  .snarr[data-has-glyph="true"] .snarr-grid { grid-template-columns: 1fr; }
  .snarr-glyph { order: -1; }
  .snarr-glyph svg { max-width: 220px; }
}

@media (max-width: 640px) {
  .snarr-grid {
    padding-left: 0;
  }
  .snarr-grid::before {
    top: -1.25rem;
    bottom: auto;
    width: 4.5rem;
    height: 3px;
  }
}
